import React from "react";
import {
  Stack,
  Card,
  CardContent,
  Typography,
  CardMedia,
  Box,
  Button,
  Dialog,
  DialogContent,
  DialogActions,
  IconButton,
} from "@mui/material";
import YouTubeEmbed from "./YouTubeEmbed";
import CloseIcon from "@mui/icons-material/Close";




const projects = [
  {
    title: "NWSL Fantasy",
    technologies: ["React Native", "NodeJS/Express", "PostgreSQL", "Supabase"],
    image: "/NWSL.png",
    description: "Fantasy League App for Women's Soccer",
    repoLink: "https://www.wosofantasy.com/",
    videoURL: "app-preview-desktop.mp4",
  },
  {
    title: "Silk Mantra",
    technologies: ["Next.js", "Tailwind CSS", "Express", "Neon"],
    image: "/SM-Logo.png",
    description: "Online Clothing Brand Store for Indian Sarees",
    repoLink: "https://silkmantra.vercel.app/",
    videoURL: "SilkMantra-new.mp4",
  },
  {
    title: "Decision Llama",
    technologies: ["React", "Material UI", "Framer Motion"],
    image: "/decisionLlama.png",
    description: "This is a description of the project.",
    repoLink: "https://decisionllama.vercel.app/",
    videoURL: "decisionllama-new.mp4",
  },
  {
    title: "BloodBuds",
    technologies: ["P2P Network", "for connecting", "blood donors/requestors", "across India"],
    image: "/bloodbuds.png", // You can replace this with actual images or icons later
    description:
      "Its a peer to peer community driven network across India for connecting blood donors to those in need",
    repoLink: "https://www.instagram.com/blood.buds/",
    videoURL: "s4ygLKsONGg&ab",
  },
  {
    title: "Lavie514",
    technologies: ["The front page", "for", "Montreal Communities", "Meet.Try.Live"],
    image: "/laviemtl.png",
    description: "This is a description of the project.",
    repoLink: "https://www.instagram.com/lavieenmtl/",
    videoURL: "DQacCB9tDaw&ab",
  },



  // Add more projects here
];

const ProjectsPage = () => {
  const [isFlipped, setIsFlipped] = React.useState(null);
  const [openDialog, setOpenDialog] = React.useState(false);
  const [selectedProject, setSelectedProject] = React.useState(null);

  const handleMouseEnter = (index) => {
    console.log("Mouse Enter");
    setIsFlipped(index); // Set the flipped card index
  };

  const handleMouseLeave = () => {
    console.log("MouseLeave");
    setIsFlipped(null); // Reset the flip on mouse leave
  };

  const handleOpenDialog = (project) => {
    setSelectedProject(project);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedProject(null);
  };

  return (
    <div className="projects-page">
      <h1>Projects</h1>
      <Stack
        direction="row"
        justifyContent="center"
        flexWrap={"wrap"}
        alignItems={"flex-start"}
        sx={{
          width: "100%", // Ensure Stack takes full width
          boxSizing: "border-box",
          marginLeft: "auto", // Adjust margin to auto-center
          marginRight: "auto", // Adjust margin to auto-center
          gap: 3, // Add gap between items
        }}
      >
        {projects.map((project, index) => (
          <Stack item xs={12} sm={6} md={4} key={index}>
            <div
              className="flip-card"
              onMouseEnter={() => handleMouseEnter(index)}
              onMouseLeave={handleMouseLeave}
              style={{ flexBasis: "calc(300 - 24px)" }}
            >
              <div
                className={`flip-card-inner ${isFlipped === index ? "flipped" : ""}`}
                style={{
                  width: 276 /* Width for the tile */,
                  height: 340 /* Height for the tile */,
                  marginBottom: 3,
                }}
              >
                <div className="flip-card-front">
                  <Card
                    sx={{
                      //  flex: "1 1 calc(300px - 24px)", // Adjust width for 3 items per row with spacing
                      width: "100%",
                      height: "100%",
                      boxSizing: "border-box",
                      boxShadow: 3,
                      backgroundImage:
                        "linear-gradient(to right bottom, #ffffff, #808080)",
                      backgroundColor: "rgba(255, 255, 255, 1)", // Off-white background
                      position: "absolute", // For positioning title over image
                    }}
                  >
                    <CardMedia
                      component="img"
                      height="180"
                      image={project.image} // Replace with actual image paths
                      alt={project.title}
                    />
                    <Box
                      sx={{
                        position: "absolute",
                        top: 120,
                        right: 0,
                        backgroundColor: "rgba(0, 0, 0, 0.7)", // Semi-transparent black background
                        color: "#fff", // White text color for contrast

                        padding: "8px 16px",
                        borderRadius: "10px 0px 0px 10px", // Rounded bottom-left corner
                        textAlign: "right", // Right-align the text
                      }}
                    >
                      <Typography variant="h6">{project.title}</Typography>
                    </Box>
                    <CardContent>
                      {project.technologies.map((tech, techIndex) => (
                        <Typography
                          key={techIndex}
                          variant="body2"
                          color="rgba(0, 0, 0)"
                          sx={{
                            margin: 0,
                            textEmphasis: "bold",
                            borderBottom:
                              techIndex !== project.technologies.length - 1
                                ? "1px solid #ddd"
                                : "none", // Add border except for the last item
                            paddingBottom: "8px",
                            textAlign: "center",
                            marginBottom: "8px",
                          }}
                        >
                          {tech}
                        </Typography>
                      ))}
                    </CardContent>
                  </Card>
                </div>
                <div className="flip-card-back">
                  <Card
                    sx={{
                      width: "100%",
                      height: "100%",
                      backgroundImage:
                        "linear-gradient(to right bottom, #838383, #2e2e2e)",
                      color: "white",
                      display: "flex",
                      textAlign: "center",
                      flexDirection: "column",
                      justifyContent: "center",
                      alignItems: "center",
                    }}
                  >
                    <Typography variant="body1" sx={{ mb: 2 }}>
                      {project.description}
                    </Typography>

                    <Button
                      onClick={() => handleOpenDialog(project)}
                      variant="contained"
                      style={{ backgroundColor: "grey" }}
                    >
                      Demo
                    </Button>

                  </Card>
                </div>
              </div>
            </div>
          </Stack>
        ))}
      </Stack>

      {/* Dialog for displaying more information */}
      {selectedProject && (
        <Dialog open={openDialog} onClose={handleCloseDialog} fullWidth maxWidth="600" PaperProps={{
          sx: {  // Adjusts width to 75% of viewport width for 3:4 ratio
            height: "calc(100vw * 1/2)",  // Calculates height based on width for 3:4 ratio
          },
        }}>

          <DialogContent sx={{
            backgroundImage: "linear-gradient(to right bottom, #838383, #2e2e2e)"
          }}>

            {/* Close button in the top-right corner */}
            <IconButton
              aria-label="close"
              onClick={handleCloseDialog}
              sx={{
                position: "absolute",
                right: 0.4,
                top: 0.4,
                color: (theme) => theme.palette.grey[500],
              }}
            >
              <CloseIcon />
            </IconButton>

            {/* Two-column grid layout */}
            <Stack spacing={2} direction="row" sx={{
              width: "100%",
              height : "100%",
              padding: 0,
            }}>
              {/* Left column (70%) for YouTube video*/}
              <Stack item xs={12} md={10} sx={{ width: "80%"}}>
                <video controls autoPlay muted playsInline width="100%" height="100%">
                  <source src={selectedProject.videoURL} type="video/mp4" />
                </video>
                {/* Source Code Button */}
                <Button
                  variant="BUTTON"
                  color="primary"
                  borderRadius="60px"
                  href={selectedProject.repoLink}
                  target="_blank"
                  rel="noopener noreferrer"
                  sx={{ 
                    width : "80%",
                    marginTop: "16px",  
                    color:"white",
                    backgroundImage: "linear-gradient(to right bottom, #44b2e6, #05044d)",
                  }}
                >
                  App Site
                </Button>
              </Stack>


              {/* Right column (30%) for project details */}
              <Stack item xs={12} md={2} sx={{
                color: "white",
                justifyItems : "center",
                paddingTop: "0px",
              }}>
                {/* Project Title */}
                <Typography variant="h6" gutterBottom>
                  {selectedProject.title}
                </Typography>

                {/* Project Description */}
                <Typography variant="body2" gutterBottom>
                  <strong>Description:</strong>
                </Typography>
                <Typography variant="caption" gutterBottom>
                  {selectedProject.description}
                </Typography>

                {/* Technologies Used
                <Typography variant="body2" gutterBottom>
                  <strong>Technologies Used:</strong>
                </Typography>
                <ul>
                  {selectedProject.technologies.map((tech, index) => (
                    <li key={index}>
                      <Typography variant="body2">{tech}</Typography>
                    </li>
                  ))}
                </ul>
                */}
              </Stack>

            </Stack>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
};

export default ProjectsPage;
